sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // FLEET-48: failed inspection -> corrective maintenance; failed CHECK_OUT also re-queues the reservation (D-02, D-15, D-22)
    var failed = [];
    if (current.tire_pressure_ok != true) {
        failed.push('tire pressure');
    }
    if (current.lights_ok != true) {
        failed.push('lights');
    }
    if (current.windshield_ok != true) {
        failed.push('windshield');
    }
    var isCheckOut = current.getValue('inspection_type') == 'CHECK_OUT';
    var desc = (isCheckOut ? 'Failed check-out inspection ' : 'Failed check-in inspection ') + current.getValue('number') +
        ': ' + failed.join(', ') + '.';
    if (current.getValue('external_damage_notes')) {
        desc += ' Notes: ' + current.getValue('external_damage_notes');
    }

    var m = new GlideRecord('x_1850693_enterp_0_maintenance');
    m.initialize();
    m.setValue('vehicle', current.getValue('vehicle'));
    m.setValue('reservation', current.getValue('reservation'));
    m.setValue('maintenance_type', 'CORRECTIVE');
    m.setValue('urgency_level', isCheckOut ? 'HIGH' : 'MEDIUM');
    m.setValue('reported_by', current.getValue('inspected_by'));
    m.setValue('repair_description', desc);
    var mId = m.insert(); // vehicle -> MAINTENANCE via "Maintenance - Sync vehicle status" when HIGH
    if (mId) {
        gs.eventQueue('x_1850693_enterp_0.maintenance.reported', m, current.getValue('vehicle'), current.getValue('reservation'));
    }

    if (!isCheckOut) {
        return; // a trip with a failed check-in can still complete
    }
    var res = new GlideRecord('x_1850693_enterp_0_reservation');
    if (res.get(current.getValue('reservation')) &&
        ['ASSIGNED', 'READY_FOR_PICKUP'].indexOf(res.getValue('reservation_state')) > -1) {
        var plate = res.assigned_vehicle.getDisplayValue();
        res.setValue('assigned_vehicle', '');
        res.setValue('check_out_odometer', '');
        res.setValue('reservation_state', 'PENDING_ASSIGNMENT');
        res.work_notes = 'Vehicle ' + plate + ' failed the check-out inspection (' + failed.join(', ') +
            '). Corrective maintenance ' + m.getValue('number') + ' raised; reservation returned to the assignment queue.';
        res.update();
    }
})(current, previous);
